import React from "react";
import DevisView from "./DevisView";
import MateriauList from "./MateriauList";
import EmployeTable from "./EmployeTable";

export default function Dashboard() {
    const devis = { typeConstruction: "MAISON", superficie: 120, coutTotal: 95000 };
    const materiaux = [
        { nom: "Ciment", quantite: "50 sacs", cout: 3000 },
        { nom: "Sable", quantite: "5 m³", cout: 1500 },
        { nom: "Fer", quantite: "1 tonne", cout: 8000 },
    ];

    return (
        <div className="space-y-6">
            <DevisView devis={devis} />
            <MateriauList materiaux={materiaux} />
            <EmployeTable />
        </div>
    );
}
